import{_ as e,o,c as a}from"./chunks/framework.D1Ss-Xl7.js";const h=JSON.parse('{"title":"cors Tag","description":"","frontmatter":{"layout":"post-list"},"headers":[],"params":{"slug":"cors","tag":"cors","title":"cors Tag","prev":null,"next":null,"posts":[{"title":"跨域请求中的cookies处理","url":"/posts/2018-09-08-cors-cookie/","date":"2018-09-08 23:07","tags":["cors","cookies"],"html":"<p>现在的前后端开发已经完全分离，后端服务器和前端服务器分别部署在不同的服务器。同时也对应不同的域名，所以跨域请求领域方面的知识也需要补充。</p>\\n<h2 id=\\"跨域请求添加-header\\" tabindex=\\"-1\\">跨域请求添加 header <a class=\\"header-anchor\\" href=\\"#跨域请求添加-header\\" aria-label=\\"Permalink to &quot;跨域请求添加 header&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>我们都知道，出于安全考虑，JS 是有同源策略限制。所以，我们在对其他域名发起请求的时候需要添加 http header。</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>Access-Control-Allow-Origin: *</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>这个参数的值只能为星号或者具体的网址，星号代表所有网站。</p>\\n<h2 id=\\"跨域请求添加-cookie\\" tabindex=\\"-1\\">跨域请求添加 cookie <a class=\\"header-anchor\\" href=\\"#跨域请求添加-cookie\\" aria-label=\\"Permalink to &quot;跨域请求添加 cookie&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>JS 跨域请求有两个 API 可以使用，<code>XMLHttpRequest</code>和<code>fetch</code>。<code>XMLHttpRequest</code>会默认带上 cookies，但是<code>fetch</code>默认不会带上。如果需要带上 cookies，需要把<code>withCredentials</code>设置为<code>true</code>。</p>\\n<h2 id=\\"跨域请求服务器设置-cookie\\" tabindex=\\"-1\\">跨域请求服务器设置 cookie <a class=\\"header-anchor\\" href=\\"#跨域请求服务器设置-cookie\\" aria-label=\\"Permalink to &quot;跨域请求服务器设置 cookie&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>我们都知道服务器设置 cookie 是通过<code>set-cookie</code>的 http header 来完成。浏览器会读取这个信息设置 cookie。但是对于跨与请求，默认是无效的。我们需要再添加一个 http header。</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>Access-Control-Allow-Credentials: true</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>当设置了这个 http header，<code>Access-Control-Allow-Origin</code>就不能设置为星号了，必须指定具体的网址。我们必须指定<code>withCredentials</code>为<code>true</code>并且<code>Access-Control-Allow-Credentials</code>为<code>true</code>的时候，服务器返回的<code>set-cookie</code>才会生效。</p>\\n<p>参考：</p>\\n<p><a href=\\"https://developer.mozilla.org/en-US/docs/Web/HTTP/Headers/Access-Control-Allow-Credentials\\" target=\\"_blank\\" rel=\\"noreferrer\\">Access-Control-Allow-Credentials</a></p>\\n<p><a href=\\"https://developer.mozilla.org/en-US/docs/Web/HTTP/CORS\\" target=\\"_blank\\" rel=\\"noreferrer\\">CORS</a></p>\\n"}]},"relativePath":"tags/cors/index.md","filePath":"tags/[slug].md"}'),s={name:"tags/cors/index.md"};function t(r,c,n,l,d,i){return o(),a("div")}const u=e(s,[["render",t]]);export{h as __pageData,u as default};
